<?php

/**
 * Generates src/Context/Bundled/<name>.php from resources/contexts/<name>.jsonld
 * for every context in resources/contexts/manifest.json.
 *
 * Usage: php bin/generate-contexts.php [resources-directory [output-directory]]
 *
 * The script checks each resource file against the SHA-256 in the manifest, and
 * it refuses a context that a PHP array cannot hold faithfully: one with an
 * empty JSON object, which would come back as an empty list, or with a
 * property name that PHP would turn into an integer key. Each generated file
 * credits its source with the title, copyright line, and license that the
 * manifest records.
 *
 * ---
 *
 * This file is part of socialweb/json-ld
 *
 * socialweb/json-ld is free software: you can redistribute it and/or modify it
 * under the terms of the GNU Lesser General Public License as published by the
 * Free Software Foundation, either version 3 of the License, or (at your
 * option) any later version.
 *
 * socialweb/json-ld is distributed in the hope that it will be useful, but
 * WITHOUT ANY WARRANTY; without even the implied warranty of MERCHANTABILITY or
 * FITNESS FOR A PARTICULAR PURPOSE. See the GNU Lesser General Public License
 * for more details.
 *
 * You should have received a copy of the GNU Lesser General Public License
 * along with socialweb/json-ld. If not, see <https://www.gnu.org/licenses/>.
 *
 * SPDX-License-Identifier: LGPL-3.0-or-later
 */

declare(strict_types=1);

$template = <<<'PHP'
    <?php

    /**
     * Generated by bin/generate-contexts.php from resources/contexts/%s.jsonld,
     * the context published at %s.
     * Do not edit this file; run "composer generate-contexts" instead.
     *
     * This file includes material copied from or derived from
     * %s,
     * %s.
     * %s
     * %s, %s.
     * See the NOTICE file for the terms.
     */

    declare(strict_types=1);

    return %s;

    PHP;

$exportString = static fn (string $value): string => "'" . strtr($value, ['\\' => '\\\\', "'" => "\\'"]) . "'";

/**
 * @var Closure(mixed, int, string): (decimal-int-string|non-empty-string) $export Returns PHP source for a decoded JSON value.
 */
$export = static function (mixed $value, int $indent, string $path) use (&$export, $exportString): string {
    $inner = str_repeat('    ', $indent + 1);
    $close = PHP_EOL . str_repeat('    ', $indent) . ']';

    if (is_object($value)) {
        $entries = get_object_vars($value);

        if (count($entries) === 0) {
            throw new RuntimeException(sprintf('%s is an empty object, which a PHP array cannot hold', $path));
        }

        $lines = [];

        foreach ($entries as $key => $entry) {
            if (is_int($key)) {
                throw new RuntimeException(
                    sprintf('%s has the property name "%d", which PHP turns into an integer', $path, $key),
                );
            }

            $lines[] = $inner . $exportString($key) . ' => ' . $export($entry, $indent + 1, $path . '/' . $key) . ',';
        }

        return '[' . PHP_EOL . implode(PHP_EOL, $lines) . $close;
    }

    if (is_array($value)) {
        if (count($value) === 0) {
            return '[]';
        }

        $lines = [];

        foreach ($value as $index => $entry) {
            $lines[] = $inner . $export($entry, $indent + 1, $path . '/' . $index) . ',';
        }

        return '[' . PHP_EOL . implode(PHP_EOL, $lines) . $close;
    }

    return match (true) {
        is_string($value) => $exportString($value),
        $value === null => 'null',
        is_bool($value) => $value ? 'true' : 'false',
        is_int($value) => (string) $value,
        // With serialize_precision set to -1 below, json_encode() writes the
        // shortest form that reads back as the same float.
        is_float($value) => json_encode($value, JSON_THROW_ON_ERROR),
        default => throw new RuntimeException(sprintf('%s is not a JSON value', $path)),
    };
};

ini_set('serialize_precision', '-1');

$resources = $argv[1] ?? __DIR__ . '/../resources/contexts';
$output = $argv[2] ?? __DIR__ . '/../src/Context/Bundled';

try {
    /**
     * @var object{contexts: list<object{
     *     name: non-empty-string,
     *     url: non-empty-string,
     *     sha256: non-empty-string,
     *     source: object{title: non-empty-string, url: non-empty-string, copyright: non-empty-string},
     *     license: object{name: non-empty-string, url: non-empty-string},
     * }>} $manifest
     */
    $manifest = json_decode((string) file_get_contents($resources . '/manifest.json'), flags: JSON_THROW_ON_ERROR);

    foreach ($manifest->contexts as $context) {
        $json = (string) file_get_contents(sprintf('%s/%s.jsonld', $resources, $context->name));

        if (hash('sha256', $json) !== $context->sha256) {
            throw new RuntimeException(
                sprintf('%s.jsonld does not match the SHA-256 in the manifest', $context->name),
            );
        }

        $document = json_decode($json, flags: JSON_THROW_ON_ERROR);
        $source = sprintf(
            $template,
            $context->name,
            $context->url,
            $context->source->title,
            $context->source->url,
            wordwrap($context->source->copyright . '.', 76, PHP_EOL . ' * '),
            $context->license->name,
            $context->license->url,
            $export($document, 0, $context->name),
        );

        file_put_contents(sprintf('%s/%s.php', $output, $context->name), $source);
        fwrite(STDOUT, sprintf('Generated %s.php', $context->name) . PHP_EOL);
    }
} catch (JsonException | RuntimeException $exception) {
    fwrite(STDERR, $exception->getMessage() . PHP_EOL);

    exit(1);
}
